#include <cstdio>
#include <cstring>
#include <vector>
#include <algorithm>
#include <queue>
#include <utility>
using namespace std;

int N, T, sinkNode;
int sourceCap[10][10], sinkCap[10][10];
int sourceId[10][10], sinkId[10][10];
int gridPlant[10][10][61];
int residual[250][250];
int dirR[4] = {0,0,-1,1};
int dirC[4] = {-1,1,0,0};

bool inBounds(int r, int c) {
    return r >= 0 && r < N && c >= 0 && c < N;
}

bool dfsAugment(int u, vector<int>& parent) {
    if (u == sinkNode) return true;
    for (int v = 0; v <= sinkNode; ++v) {
        if (residual[u][v] > 0 && parent[v] == -1) {
            parent[v] = u;
            if (dfsAugment(v, parent)) return true;
        }
    }
    return false;
}

int getAugment() {
    vector<int> parent(sinkNode + 1, -1);
    parent[0] = 0;
    if (!dfsAugment(0, parent)) return 0;
    int add = 10000;
    for (int v = sinkNode; v != 0; v = parent[v]) add = min(add, residual[parent[v]][v]);
    for (int v = sinkNode; v != 0; v = parent[v]) {
        residual[parent[v]][v] -= add;
        residual[v][parent[v]] += add;
    }
    return add;
}

int main() {
    scanf("%d%d", &N, &T);
    char g[10][11];
    for (int i = 0; i < N; ++i) scanf("%s", g[i]);

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            if (g[i][j] == 'Y' || g[i][j] == 'Z') {
                gridPlant[i][j][0] = g[i][j] - 'X';
                sourceCap[i][j] = 0;
            } else {
                gridPlant[i][j][0] = 0;
                sourceCap[i][j] = g[i][j] - '0';
            }
        }

    for (int i = 0; i < N; ++i) scanf("%s", g[i]);

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            if (g[i][j] == 'Y' || g[i][j] == 'Z') {
                gridPlant[i][j][0] = g[i][j] - 'X';
                sinkCap[i][j] = 0;
            } else {
                gridPlant[i][j][0] = 0;
                sinkCap[i][j] = g[i][j] - '0';
            }
        }

    for (int time = 1; time <= T; ++time) {
        for (int i = 0; i < N; ++i)
            for (int j = 0; j < N; ++j)
                gridPlant[i][j][time] = gridPlant[i][j][time-1];

        for (int i = 0; i < N; ++i)
            for (int j = 0; j < N; ++j)
                if (gridPlant[i][j][time-1] == 2)
                    for (int d = 0; d < 4; ++d) {
                        int ni = i + dirR[d], nj = j + dirC[d];
                        if (inBounds(ni, nj) && gridPlant[ni][nj][time-1] == 0)
                            gridPlant[ni][nj][time] = 2;
                    }
    }

    memset(sourceId, -1, sizeof(sourceId));
    memset(sinkId, -1, sizeof(sinkId));
    sinkNode = 1;
    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (sourceCap[i][j] != 0) sourceId[i][j] = sinkNode++;

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j)
            if (sinkCap[i][j] != 0) sinkId[i][j] = sinkNode++;

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            if (sourceCap[i][j] == 0) continue;
            vector<vector<bool>> seen(N, vector<bool>(N, false));
            queue<pair<int,pair<int,int>>> q;
            q.push(make_pair(0, make_pair(i, j)));
            seen[i][j] = true;
            int src = sourceId[i][j];
            while (!q.empty()) {
                int time = q.front().first;
                int r = q.front().second.first;
                int c = q.front().second.second;
                q.pop();
                if (sinkCap[r][c] != 0) residual[src][sinkId[r][c]] = 10000;
                if (time == T) continue;
                if (gridPlant[r][c][time] != 0) continue;
                for (int d = 0; d < 4; ++d) {
                    int nr = r + dirR[d], nc = c + dirC[d];
                    if (inBounds(nr, nc) && gridPlant[nr][nc][time] == 0 && !seen[nr][nc]) {
                        seen[nr][nc] = true;
                        q.push(make_pair(time+1, make_pair(nr, nc)));
                    }
                }
            }
        }

    for (int i = 0; i < N; ++i)
        for (int j = 0; j < N; ++j) {
            if (sourceCap[i][j] != 0) residual[0][sourceId[i][j]] = sourceCap[i][j];
            if (sinkCap[i][j] != 0) residual[sinkId[i][j]][sinkNode] = sinkCap[i][j];
        }

    int total = 0, flow;
    while ((flow = getAugment()) != 0) total += flow;
    printf("%d\n", total);
    return 0;
}
